// File: rtl/GP.v
module GP (
    input  wire i_A,
    input  wire i_B,
    input  wire i_Cin,
    output wire o_generate,
    output wire o_propagate,
    output wire o_Cout
);

    // Generate signal: high when both operand bits are 1
    assign o_generate = i_A & i_B;

    // Propagate signal: high when at least one operand bit is 1
    assign o_propagate = i_A | i_B;

    // Carry-out: generated by local inputs or propagated from carry-in
    assign o_Cout = o_generate | (o_propagate & i_Cin);

endmodule

