module axi_register #(
    parameter integer ADDR_WIDTH = 32,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    clk_i,
    input  wire                    rst_n_i,
    input  wire [ADDR_WIDTH-1:0]   awaddr_i,
    input  wire                    awvalid_i,
    output wire                    awready_o,
    input  wire [DATA_WIDTH-1:0]   wdata_i,
    input  wire                    wvalid_i,
    output wire                    wready_o,
    input  wire [(DATA_WIDTH/8)-1:0] wstrb_i,
    input  wire                    bready_i,
    output wire [1:0]              bresp_o,
    output wire                    bvalid_o,
    input  wire [ADDR_WIDTH-1:0]   araddr_i,
    input  wire                    arvalid_i,
    output wire                    arready_o,
    output wire [DATA_WIDTH-1:0]   rdata_o,
    output wire                    rvalid_o,
    output wire [1:0]              rresp_o,
    input  wire                    done_i,
    output wire [19:0]             beat_o,
    output wire                    start_o,
    output wire                    writeback_o
);

    // Internal Registers
    logic [DATA_WIDTH-1:0] reg_beat;
    logic                  reg_start;
    logic                  reg_done;
    logic                  reg_writeback;

    // Address Decoding
    logic [2:0] w_addr_sel;
    logic [2:0] r_addr_sel;

    always_comb begin
        case (awaddr_i)
            32'h0000_0100: w_addr_sel = 3'd0;
            32'h0000_0200: w_addr_sel = 3'd1;
            32'h0000_0300: w_addr_sel = 3'd2;
            32'h0000_0400: w_addr_sel = 3'd3;
            32'h0000_0500: w_addr_sel = 3'd4;
            default:       w_addr_sel = 3'd5;
        endcase
    end

    always_comb begin
        case (araddr_i)
            32'h0000_0100: r_addr_sel = 3'd0;
            32'h0000_0200: r_addr_sel = 3'd1;
            32'h0000_0300: r_addr_sel = 3'd2;
            32'h0000_0400: r_addr_sel = 3'd3;
            32'h0000_0500: r_addr_sel = 3'd4;
            default:       r_addr_sel = 3'd5;
        endcase
    end

    // Write FSM
    typedef enum logic [1:0] { AW_IDLE, AW_WAIT, AW_DATA, AW_RESP } aw_fsm_t;
    aw_fsm_t aw_state, aw_next;

    // Read FSM
    typedef enum logic [1:0] { AR_IDLE, AR_WAIT, AR_DATA } ar_fsm_t;
    ar_fsm_t ar_state, ar_next;

    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            aw_state <= AW_IDLE;
            ar_state <= AR_IDLE;
            reg_beat <= '0;
            reg_start <= '0;
            reg_done <= '0;
            reg_writeback <= '0;
        end else begin
            // Write FSM State Transition
            case (aw_state)
                AW_IDLE:    aw_next <= awvalid_i ? AW_WAIT : AW_IDLE;
                AW_WAIT:    aw_next <= (awvalid_i & awready_o) ? AW_DATA : (awvalid_i ? AW_WAIT : AW_IDLE);
                AW_DATA:    aw_next <= (wvalid_i & wready_o) ? AW_RESP : (wvalid_i ? AW_DATA : AW_DATA);
                AW_RESP:    aw_next <= (bready_i & bvalid_o) ? AW_IDLE : AW_RESP;
                default:    aw_next <= AW_IDLE;
            endcase

            // Read FSM State Transition
            case (ar_state)
                AR_IDLE:    ar_next <= arvalid_i ? AR_WAIT : AR_IDLE;
                AR_WAIT:    ar_next <= (arvalid_i & arready_o) ? AR_DATA : (arvalid_i ? AR_WAIT : AR_IDLE);
                AR_DATA:    ar_next <= (rready_i & rvalid_o) ? AR_IDLE : AR_DATA;
                default:    ar_next <= AR_IDLE;
            endcase

            aw_state <= aw_next;
            ar_state <= ar_next;

            // Register Updates on Valid Write Handshake
            if (wvalid_i & wready_o) begin
                logic full_write;
                full_write = (&wstrb_i) && (wstrb_i != 0);
                if (full_write) begin
                    case (w_addr_sel)
                        3'd0: reg_beat  <= wdata_i[19:0];
                        3'd1: reg_start <= wdata_i[0];
                        3'd2: reg_done  <= ~wdata_i[0]; // Clear done status
                        3'd3: reg_writeback <= wdata_i[0];
                        3'd4: ; // ID is Read-Only, no update
                        default: ;
                    endcase
                end
            end

            // Hardware done status input updates register
            reg_done <= reg_done | done_i;
        end
    end

    // Handshake & Response Signals
    assign awready_o = (aw_state == AW_IDLE) || (aw_state == AW_WAIT);
    assign wready_o  = (aw_state == AW_DATA);
    assign bvalid_o  = (aw_state == AW_RESP);
    assign bresp_o   = (w_addr_sel == 3'd4 || w_addr_sel == 3'd5) ? 2'b10 : 2'b00;

    assign arready_o = (ar_state == AR_IDLE) || (ar_state == AR_WAIT);
    assign rvalid_o  = (ar_state == AR_DATA);
    assign rresp_o   = (r_addr_sel == 3'd4 || r_addr_sel == 3'd5) ? 2'b10 : 2'b00;

    // Read Data Mux
    always_comb begin
        case (r_addr_sel)
            3'd0: rdata_o = {DATA_WIDTH-20'd0, reg_beat[19:0]};
            3'd1: rdata_o = {DATA_WIDTH-1'd0, reg_start};
            3'd2: rdata_o = {DATA_WIDTH-1'd0, reg_done};
            3'd3: rdata_o = {DATA_WIDTH-1'd0, reg_writeback};
            3'd4: rdata_o = 32'h0001_0001;
            default: rdata_o = '0;
        endcase
    end

    // Output Assignments
    assign beat_o    = reg_beat[19:0];
    assign start_o   = reg_start;
    assign writeback_o = reg_writeback;

endmodule

output.rtl/axis_upscale.sv:
module axis_upscale (
    input  wire        clk,
    input  wire        resetn,
    input  wire        dfmt_enable,
    input  wire        dfmt_type,
    input  wire        dfmt_se,
    input  wire        s_axis_valid,
    input  wire [23:0] s_axis_data,
    input  wire        m_axis_ready,
    output wire        s_axis_ready,
    output reg         m_axis_valid,
    output reg [31:0]  m_axis_data
);

    // AXI-Stream ready handshake: pass through m_axis_ready to s_axis_ready
    assign s_axis_ready = m_axis_ready;

    // Determine the base extension bit based on sign extension enable
    wire base_ext = dfmt_se ? s_axis_data[23] : 1'b0;

    // Apply inversion if dfmt_type is asserted
    wire ext_bit  = base_ext ^ dfmt_type;

    // Construct the 32-bit output data
    // When dfmt_enable is high: extend ext_bit to the upper 8 bits [31:24]
    // When dfmt_enable is low: zero-extend the input data (upper 8 bits are 0)
    wire [31:0] data_out = dfmt_enable ? { {8{ext_bit}}, s_axis_data } : { 8'b0, s_axis_data };

    // Single pipeline register stage for output data and valid signal
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            m_axis_data  <= 32'b0;
            m_axis_valid <= 1'b0;
        end else begin
            if (s_axis_valid && m_axis_ready) begin
                m_axis_data  <= data_out;
                m_axis_valid <= 1'b1;
            end else begin
                m_axis_valid <= 1'b0;
            end
        end
    end

endmodule

output.rtl/precision_counter_axi.sv:
`timescale 1ns / 1ps

module precision_counter_axi #(
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_ADDR_WIDTH = 8
) (
    input  wire                           axi_aclk,
    input  wire                           axi_aresetn,

    // Write Address Channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]  axi_awaddr,
    input  wire                           axi_awvalid,
    output wire                           axi_awready,

    // Write Data Channel
    input  wire [C_S_AXI_DATA_WIDTH-1:0]  axi_wdata,
    input  wire [(C_S_AXI_DATA_WIDTH/8)-1:0] axi_wstrb,
    input  wire                           axi_wvalid,
    output wire                           axi_wready,

    // Write Response Channel
    output wire [1:0]                     axi_bresp,
    output wire                           axi_bvalid,
    input  wire                           axi_bready,

    // Read Address Channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]  axi_araddr,
    input  wire                           axi_arvalid,
    output wire                           axi_arready,

    // Read Data Channel
    output wire [C_S_AXI_DATA_WIDTH-1:0]  axi_rdata,
    output wire [1:0]                     axi_rresp,
    output wire                           axi_rvalid,
    input  wire                           axi_rready,

    // Control Outputs
    output wire                           axi_ap_done,
    output wire                           irq
);

    // Internal State Registers for AXI Handshaking
    reg [C_S_AXI_ADDR_WIDTH-1:0] awaddr_reg;
    reg [C_S_AXI_ADDR_WIDTH-1:0] araddr_reg;
    reg [C_S_AXI_DATA_WIDTH-1:0] wdata_reg;
    reg aw_valid_reg;
    reg w_valid_reg;
    reg ar_valid_reg;

    // User Defined Registers
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_ctl;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_t;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_v;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_irq_mask;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_irq_thresh;

    // Address Decoding
    // Only offsets 0x00, 0x10, 0x20, 0x24, 0x28 are valid. Others trigger SLVERR.
    wire addr_valid = (awaddr_reg[7:0] == 8'h00) || (awaddr_reg[7:0] == 8'h10) || 
                      (awaddr_reg[7:0] == 8'h20) || (awaddr_reg[7:0] == 8'h24) || 
                      (awaddr_reg[7:0] == 8'h28);
    wire addr_valid_r = (araddr_reg[7:0] == 8'h00) || (araddr_reg[7:0] == 8'h10) || 
                        (araddr_reg[7:0] == 8'h20) || (araddr_reg[7:0] == 8'h24) || 
                        (araddr_reg[7:0] == 8'h28);

    // AXI Handshake Assignments
    assign axi_awready = !aw_valid_reg;
    assign axi_wready  = !w_valid_reg;
    assign axi_arready = !ar_valid_reg;

    // Write Response
    assign axi_bvalid = w_valid_reg;
    assign axi_bresp  = addr_valid ? 2'b00 : 2'b10;

    // Read Response
    assign axi_rvalid = ar_valid_reg;
    assign axi_rresp  = addr_valid_r ? 2'b00 : 2'b10;

    // Read Data Mux
    assign axi_rdata = (araddr_reg[7:0] == 8'h00) ? slv_reg_ctl :
                       (araddr_reg[7:0] == 8'h10) ? slv_reg_t :
                       (araddr_reg[7:0] == 8'h20) ? slv_reg_v :
                       (araddr_reg[7:0] == 8'h24) ? slv_reg_irq_mask :
                       (araddr_reg[7:0] == 8'h28) ? slv_reg_irq_thresh : {C_S_AXI_DATA_WIDTH{1'b0}};

    // Control Outputs
    assign axi_ap_done = (slv_reg_v == 0) ? 1'b1 : 1'b0;

    // Interrupt Logic
    reg irq_reg;
    assign irq = irq_reg;

    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            irq_reg <= 1'b0;
        end else begin
            irq_reg <= 1'b0;
            // Cleared when countdown stops or threshold condition no longer met
            if (slv_reg_ctl[0] == 0) begin
                irq_reg <= 1'b0;
            end else if (slv_reg_irq_mask[0] && slv_reg_v == slv_reg_irq_thresh) begin
                irq_reg <= 1'b1;
            end
        end
    end

    // AXI Write Address Channel FSM
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            aw_valid_reg <= 1'b0;
            awaddr_reg   <= {C_S_AXI_ADDR_WIDTH{1'b0}};
        end else begin
            if (axi_awvalid && !aw_valid_reg) begin
                awaddr_reg   <= axi_awaddr;
                aw_valid_reg <= 1'b1;
            end else if (axi_bready && axi_bvalid) begin
                aw_valid_reg <= 1'b0;
            end
        end
    end

    // AXI Write Data Channel FSM
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            w_valid_reg <= 1'b0;
            wdata_reg   <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else begin
            if (axi_wvalid && !w_valid_reg) begin
                wdata_reg   <= axi_wdata;
                w_valid_reg <= 1'b1;
            end else if (axi_bready && axi_bvalid) begin
                w_valid_reg <= 1'b0;
            end
        end
    end

    // AXI Read Address Channel FSM
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            ar_valid_reg <= 1'b0;
            araddr_reg   <= {C_S_AXI_ADDR_WIDTH{1'b0}};
        end else begin
            if (axi_arvalid && !ar_valid_reg) begin
                araddr_reg   <= axi_araddr;
                ar_valid_reg <= 1'b1;
            end else if (axi_rready && axi_rvalid) begin
                ar_valid_reg <= 1'b0;
            end
        end
    end

    // Register Update Logic on Write
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            slv_reg_ctl        <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_t          <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_v          <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_irq_mask   <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_irq_thresh <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else begin
            // Apply write when data is latched and response is accepted by master
            if (w_valid_reg && axi_bready) begin
                case (awaddr_reg[7:0])
                    8'h00: begin
                        slv_reg_ctl  <= axi_wdata;
                        slv_reg_t    <= {C_S_AXI_DATA_WIDTH{1'b0}}; // Reset elapsed time on control write
                    end
                    8'h20: begin
                        slv_reg_v    <= axi_wdata;
                    end
                    8'h24: begin
                        slv_reg_irq_mask <= axi_wdata;
                    end
                    8'h28: begin
                        slv_reg_irq_thresh <= axi_wdata;
                    end
                    default: begin
                        // Ignored for invalid/reserved addresses
                    end
                endcase
            end
        end
    end

    // Countdown & Elapsed Time Logic
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            slv_reg_v <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_t <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else begin
            // Elapsed time increments when countdown is finished (v==0) and counter is active
            if (slv_reg_v == 0 && slv_reg_ctl[0])
                slv_reg_t <= slv_reg_t + 1;

            // Countdown decrements while running
            if (slv_reg_ctl[0]) begin
                if (slv_reg_v > 0)
                    slv_reg_v <= slv_reg_v - 1;
            end
        end
    end

endmodule

output.rtl/axis_joiner.sv:
`timescale 1ns / 1ps

module axis_joiner (
  input wire                clk,
  input wire                rst,

  input wire  [7:0]         s_axis_tdata_1,
  input wire                s_axis_tvalid_1,
  output wire               s_axis_tready_1,
  input wire                s_axis_tlast_1,

  input wire  [7:0]         s_axis_tdata_2,
  input wire                s_axis_tvalid_2,
  output wire               s_axis_tready_2,
  input wire                s_axis_tlast_2,

  input wire  [7:0]         s_axis_tdata_3,
  input wire                s_axis_tvalid_3,
  output wire               s_axis_tready_3,
  input wire                s_axis_tlast_3,

  output wire [7:0]         m_axis_tdata,
  output wire               m_axis_tvalid,
  input  wire               m_axis_tready,
  output wire               m_axis_tlast,
  output wire [1:0]         m_axis_tuser,
  output wire               busy
);

  // Parameters for states
  localparam [1:0] STATE_IDLE = 2'd0;
  localparam [1:0] STATE_1    = 2'd1;
  localparam [1:0] STATE_2    = 2'd2;
  localparam [1:0] STATE_3    = 2'd3;

  // Internal registers
  reg    [1:0]    state;
  reg             temp;

  reg    [7:0]    m_axis_tdata_reg;
  reg             m_axis_tlast_reg;
  reg    [1:0]    m_axis_tuser_reg;

  // Mux selection wires
  wire   [7:0]    mux_data;
  wire            mux_tlast;
  wire   [1:0]    mux_user;

  // Mux logic (Combinational)
  always_comb begin
    case (state)
      STATE_IDLE: begin
        if (s_axis_tvalid_1) begin
          mux_data    = s_axis_tdata_1;
          mux_tlast   = s_axis_tlast_1;
          mux_user    = 2'h1;
        end else if (s_axis_tvalid_2) begin
          mux_data    = s_axis_tdata_2;
          mux_tlast   = s_axis_tlast_2;
          mux_user    = 2'h2;
        end else if (s_axis_tvalid_3) begin
          mux_data    = s_axis_tdata_3;
          mux_tlast   = s_axis_tlast_3;
          mux_user    = 2'h3;
        end else begin
          mux_data    = 8'd0;
          mux_tlast   = 1'b0;
          mux_user    = 2'd0;
        end
      end
      STATE_1: begin
        mux_data    = s_axis_tdata_1;
        mux_tlast   = s_axis_tlast_1;
        mux_user    = 2'h1;
      end
      STATE_2: begin
        mux_data    = s_axis_tdata_2;
        mux_tlast   = s_axis_tlast_2;
        mux_user    = 2'h2;
      end
      STATE_3: begin
        mux_data    = s_axis_tdata_3;
        mux_tlast   = s_axis_tlast_3;
        mux_user    = 2'h3;
      end
      default: begin
        mux_data    = 8'd0;
        mux_tlast   = 1'b0;
        mux_user    = 2'd0;
      end
    endcase
  end

  // Ready signals for inputs (Backpressure)
  assign s_axis_tready_1 = (state == STATE_1) ? m_axis_tready : 1'b0;
  assign s_axis_tready_2 = (state == STATE_2) ? m_axis_tready : 1'b0;
  assign s_axis_tready_3 = (state == STATE_3) ? m_axis_tready : 1'b0;

  // Output valid signal
  assign m_axis_tvalid = (state != STATE_IDLE) ? 1'b1 : 1'b0;

  // Status signal
  assign busy = (state != STATE_IDLE) ? 1'b1 : 1'b0;

  // Registered outputs
  assign m_axis_tdata  = m_axis_tdata_reg;
  assign m_axis_tlast  = m_axis_tlast_reg;
  assign m_axis_tuser  = m_axis_tuser_reg;

  // FSM and Buffering Logic
  always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
      state          <= STATE_IDLE;
      m_axis_tdata_reg <= 8'd0;
      m_axis_tlast_reg <= 1'b0;
      m_axis_tuser_reg <= 2'd0;
      temp           <= 1'b0;
    end else begin
      // Update temp flag based on stall condition
      // temp is high when module is processing and output is stalled
      temp <= (state != STATE_IDLE && ~m_axis_tready) ? 1'b1 : 1'b0;

      // Data buffering logic
      if (temp) begin
        // Hold data when stalled
        m_axis_tdata_reg <= m_axis_tdata_reg;
        m_axis_tlast_reg <= m_axis_tlast_reg;
        m_axis_tuser_reg <= m_axis_tuser_reg;
      end else begin
        // Update registers with muxed values when ready or not busy
        m_axis_tdata_reg <= mux_data;
        m_axis_tlast_reg <= mux_tlast;
        m_axis_tuser_reg <= mux_user;
      end

      // State transitions
      case (state)
        STATE_IDLE: begin
          // Priority arbitration: 1 > 2 > 3
          if (s_axis_tvalid_1) begin
            state <= STATE_1;
          end else if (s_axis_tvalid_2) begin
            state <= STATE_2;
          end else if (s_axis_tvalid_3) begin
            state <= STATE_3;
          end else begin
            state <= STATE_IDLE;
          end
        end
        STATE_1: begin
          // Stay in STATE_1 until packet completes from source 1
          // Packet completes when valid, ready, and tlast is asserted on the beat
          if (s_axis_tvalid_1 && m_axis_tready && s_axis_tlast_1) begin
            state <= STATE_IDLE;
          end else begin
            state <= STATE_1;
          end
        end
        STATE_2: begin
          if (s_axis_tvalid_2 && m_axis_tready && s_axis_tlast_2) begin
            state <= STATE_IDLE;
          end else begin
            state <= STATE_2;
          end
        end
        STATE_3: begin
          if (s_axis_tvalid_3 && m_axis_tready && s_axis_tlast_3) begin
            state <= STATE_IDLE;
          end else begin
            state <= STATE_3;
          end
        end
        default: begin
          state <= STATE_IDLE;
        end
      endcase
    end
  end

endmodule

output.rtl/binary_to_one_hot_decoder.v:
module binary_to_one_hot_decoder # (
    parameter BINARY_WIDTH = 5,
    parameter OUTPUT_WIDTH = 32
) (
    input wire [BINARY_WIDTH-1:0] binary_in,
    output reg [OUTPUT_WIDTH-1:0] one_hot_out
);

    // Combinational logic for binary to one-hot decoding
    always @* begin
        // Default to all zeros
        one_hot_out = {OUTPUT_WIDTH{1'b0}};

        // Set the corresponding bit to 1 if within valid range
        if (binary_in < OUTPUT_WIDTH) begin
            one_hot_out[binary_in] = 1'b1;
        end
    end

endmodule

output.rtl/car_parking_system.sv:
module car_parking_system #(
    parameter int TOTAL_SPACES = 12,
    parameter int SPACE_WIDTH  = $clog2(TOTAL_SPACES)
)(
    input  wire                    clk,
    input  wire                    reset,
    input  wire                    vehicle_entry_sensor,
    input  wire                    vehicle_exit_sensor,
    output wire [SPACE_WIDTH-1:0]  available_spaces,
    output wire [SPACE_WIDTH-1:0]  count_car,
    output wire                    led_status,
    output wire [6:0]              seven_seg_display_available_tens,
    output wire [6:0]              seven_seg_display_available_units,
    output wire [6:0]              seven_seg_display_count_tens,
    output wire [6:0]              seven_seg_display_count_units
);

    // FSM State Encoding
    localparam logic [1:0] IDLE  = 2'b00;
    localparam logic [1:0] ENTRY = 2'b01;
    localparam logic [1:0] EXIT  = 2'b10;
    localparam logic [1:0] FULL  = 2'b11;

    // Internal Registers
    logic [SPACE_WIDTH-1:0] avail_r, count_r;
    logic [1:0] state_r, state_n;

    // 7-Segment Encoder Function
    // MSB = Segment A, LSB = Segment G
    function [6:0] encode_7seg(input int digit);
        case(digit)
            0: return 7'b0111111;
            1: return 7'b0000110;
            2: return 7'b1011011;
            3: return 7'b1001111;
            4: return 7'b1100110;
            5: return 7'b1101101;
            6: return 7'b1111101;
            7: return 7'b0000111;
            8: return 7'b1111111;
            9: return 7'b1101111;
            default: return 7'b0000000;
        endcase
    endfunction

    // Combinational Next-State Logic
    always @(*) begin
        case (state_r)
            IDLE: begin
                if (vehicle_entry_sensor) state_n = ENTRY;
                else if (vehicle_exit_sensor) state_n = EXIT;
                else state_n = IDLE;
            end
            ENTRY: begin
                // After entry, check if parking becomes full
                state_n = (avail_r - 1'd1 == 0) ? FULL : IDLE;
            end
            EXIT: begin
                // After exit, parking is never full
                state_n = IDLE;
            end
            FULL: begin
                // Deny entry, allow exit
                state_n = (vehicle_exit_sensor) ? EXIT : FULL;
            end
            default: state_n = IDLE;
        endcase
    end

    // Sequential Logic (State & Data Updates)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_r <= IDLE;
            avail_r <= TOTAL_SPACES;
            count_r <= 0;
        end else begin
            state_r <= state_n;
            case (state_r)
                ENTRY: begin
                    avail_r <= avail_r - 1'd1;
                    count_r <= count_r + 1'd1;
                end
                EXIT: begin
                    avail_r <= avail_r + 1'd1;
                    count_r <= count_r - 1'd1;
                end
                default: begin
                    // No data update in IDLE or FULL states
                end
            endcase
        end
    end

    // Output Assignments
    assign available_spaces = avail_r;
    assign count_car        = count_r;
    assign led_status       = (avail_r == 0) ? 1'b0 : 1'b1;

    // Display Digit Extraction (Supports up to 2 digits / 99)
    logic [3:0] avail_tens, avail_units, count_tens, count_units;
    assign avail_tens  = (avail_r >= 10) ? avail_r / 10 : 4'b0;
    assign avail_units = avail_r % 10;
    assign count_tens  = (count_r >= 10) ? count_r / 10 : 4'b0;
    assign count_units = count_r % 10;

    // 7-Segment Display Encoding
    assign seven_seg_display_available_tens  = encode_7seg(avail_tens);
    assign seven_seg_display_available_units = encode_7seg(avail_units);
    assign seven_seg_display_count_tens      = encode_7seg(count_tens);
    assign seven_seg_display_count_units     = encode_7seg(count_units);

endmodule

